mapper.select:
SELECT ats.id AS sessionId, ats.course_id AS courseId, c.name AS courseName, ats.teacher_id AS teacherId, u.real_name AS teacherName, ats.session_date AS sessionDate, ats.duration AS duration, ats.status AS status FROM attendance_session ats INNER JOIN course c ON ats.course_id = c.id INNER JOIN sys_user u ON ats.teacher_id = u.id
AND ats.teacher_id = #{teacherId}
AND ats.course_id = #{courseId}
ORDER BY ats.session_date DESC, ats.id DESC LIMIT #{limit}

SELECT c.id AS id, c.name AS courseName FROM course c WHERE c.status = 1
AND c.teacher_id = #{teacherId}
ORDER BY c.id DESC
